import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AccountLookupServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("AccountLookup");
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String accountId = req.getParameter("id");
        String fields = req.getParameter("fields");

        // Validate accountId is numeric
        if (accountId == null || !accountId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid account ID");
            return;
        }

        // Fields parameter allows selecting which columns to return
        // Default to safe subset
        if (fields == null || fields.isEmpty()) {
            fields = "account_name, account_type, created_date";
        } else {
            // Remove obviously dangerous characters but allow column names
            fields = fields.replaceAll("[;{}()]", "");
            // Limit length to prevent abuse
            if (fields.length() > 200) {
                resp.sendError(400, "Fields parameter too long");
                return;
            }
        }

        String query = "SELECT " + fields + " FROM accounts WHERE account_id = " + accountId;
        log.info("Executing query: " + query);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout to prevent long-running queries
            stmt.setQueryTimeout(5);

            ResultSet rs = stmt.executeQuery(query);
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{");

            ResultSetMetaData meta = rs.getMetaData();
            if (rs.next()) {
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    if (i > 1) out.print(",");
                    out.print("\"" + meta.getColumnLabel(i) + "\":");
                    String val = rs.getString(i);
                    out.print(val == null ? "null" : "\"" + val.replace("\"", "\\\"") + "\"");
                }
            }
            out.print("}");
            out.flush();
        } catch (SQLException e) {
            log.warning("SQL error: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST creates a new account - uses parameterized query
        String name = req.getParameter("name");
        String type = req.getParameter("type");

        if (name == null || type == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        String insertSql = "INSERT INTO accounts (account_name, account_type, created_date) VALUES (?, ?, CURRENT_TIMESTAMP)";
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement pstmt = conn.prepareStatement(insertSql, Statement.RETURN_GENERATED_KEYS)) {
            pstmt.setString(1, name);
            pstmt.setString(2, type);
            pstmt.executeUpdate();

            ResultSet keys = pstmt.getGeneratedKeys();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            if (keys.next()) {
                out.print("{\"id\":" + keys.getLong(1) + "}");
            }
            out.flush();
        } catch (SQLException e) {
            log.warning("Insert error: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }
}
